import json
from playwright.sync_api import sync_playwright
BASE = "http://127.0.0.1:3301/tests/alunix-r8/runs/V3c/index.html"

with sync_playwright() as p:
    b = p.chromium.launch()
    for w, h in [(1440, 900), (390, 844)]:
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(BASE, wait_until="networkidle")
        pg.wait_for_timeout(400)
        r = pg.evaluate("""() => {
          const stagger = document.querySelector('.stagger');
          const process = document.getElementById('process');
          return { start: stagger.getBoundingClientRect().top + window.scrollY - 900, end: process.getBoundingClientRect().top + window.scrollY };
        }""")
        start, end = r["start"], r["end"]
        stops_before = []
        y = start
        while y <= end:
            pg.evaluate(f"window.scrollTo(0,{max(0,y)})")
            pg.wait_for_timeout(250)
            wraps = pg.evaluate("""() => [...document.querySelectorAll('.frame-wrap')].map(w => {
              const r = w.getBoundingClientRect();
              return { cls: w.className, cv: getComputedStyle(w).contentVisibility, top: r.top, bottom: r.bottom };
            })""")
            for wr in wraps:
                if wr["top"] < h and wr["bottom"] > 0 and "is-asleep" in wr["cls"]:
                    stops_before.append({"y": y, "wrap": wr})
            y += 300
        pg.wait_for_timeout(2500)
        print(f"{w}x{h}: stops with sleeping wrapper in viewport = {len(stops_before)}")
        for s in stops_before[:5]:
            print("  ", s)
        # sleep check
        pg.evaluate("window.scrollTo(0,0)")
        pg.wait_for_timeout(1500)
        wraps_final = pg.evaluate("""() => [...document.querySelectorAll('.frame-wrap')].map(w => ({cls: w.className, src: w.querySelector('iframe') ? w.querySelector('iframe').src : null}))""")
        print(f"{w}x{h} after scrollTo(0): {wraps_final}")
        pg.close()
    b.close()

