from playwright.sync_api import sync_playwright
import time
BASE = "http://127.0.0.1:3301/tests/alunix-r8/runs/V3c/index.html"

def measure(n=200):
    with sync_playwright() as p:
        b = p.chromium.launch()
        ctx = b.new_context(viewport={"width":1440,"height":900})
        pg = ctx.new_page()
        cdp = ctx.new_cdp_session(pg)
        cdp.send("Emulation.setCPUThrottlingRate", {"rate": 1})
        pg.goto(BASE, wait_until="load")
        pg.wait_for_timeout(400)
        # scroll into process act
        y = pg.evaluate("document.getElementById('process').getBoundingClientRect().top + window.scrollY + 200")
        pg.evaluate(f"window.scrollTo(0,{y})")
        pg.wait_for_timeout(500)
        pg.evaluate("window.__scFreezeMotion = true")
        pg.wait_for_timeout(200)
        el_handle = "document.getElementById('process')"
        # warm up
        pg.evaluate(f"""() => {{
          const el = {el_handle};
          for (let i=0;i<10;i++){{ el.style.setProperty('--sc-ps', String(0.3 + i*0.0001)); el.offsetTop; }}
        }}""")
        result = pg.evaluate(f"""(n) => {{
          const el = {el_handle};
          const t0 = performance.now();
          for (let i=0;i<n;i++){{
            el.style.setProperty('--sc-ps', String(0.3 + i*0.0001));
            el.offsetTop; // force sync recalc+layout
          }}
          const t1 = performance.now();
          return (t1 - t0) / n;
        }}""", n)
        print("ms per write (with forced sync recalc):", result)
        b.close()
        return result

measure()
EOF
