with sync_playwright() as p:
    b = p.chromium.launch()
    pg = b.new_page(viewport={"width": 1440, "height": 900})
    pg.goto(BASE, wait_until="load")
    pg.wait_for_timeout(400)
    s1_at_0 = pg.evaluate("getComputedStyle(document.getElementById('process')).getPropertyValue('--s1')")
    y = pg.evaluate("document.getElementById('process').getBoundingClientRect().top + window.scrollY + 2000")
    pg.evaluate(f"window.scrollTo(0,{y})")
    pg.wait_for_timeout(300)
    pg.evaluate("window.dispatchEvent(new Event('resize'))")
    pg.wait_for_timeout(300)
    s1_after_resize = pg.evaluate("getComputedStyle(document.getElementById('process')).getPropertyValue('--s1')")
    print("s1 at scrollY=0:", s1_at_0)
    print("s1 after resize mid-act:", s1_after_resize)
    print("diff:", abs(float(s1_at_0) - float(s1_after_resize)))

    # prosa opacity check
    pg2 = b.new_page(viewport={"width": 390, "height": 844})
    pg2.goto(BASE, wait_until="load")
    pg2.wait_for_timeout(400)
    target_y = pg2.evaluate("""() => {
      const el = document.getElementById('process');
      const r = el.getBoundingClientRect();
      const vh = window.innerHeight;
      const h = r.height;
      return r.top + window.scrollY - vh + (h + vh) / 11;
    }""")
    pg2.evaluate(f"window.scrollTo(0,{target_y})")
