from playwright.sync_api import sync_playwright
BASE = "http://127.0.0.1:3301/tests/alunix-r8/runs/V3c/index.html"
with sync_playwright() as p:
    b = p.chromium.launch()
    ctx = b.new_context(viewport={"width": 1440, "height": 900}, reduced_motion="reduce")
    pg = ctx.new_page()
    pg.goto(BASE, wait_until="load")
    pg.wait_for_timeout(500)
    def sample(x, y):
        shot = pg.screenshot()
        from PIL import Image
        import io
        im = Image.open(io.BytesIO(shot))
        return im.getpixel((x, y))
    px_fold = sample(1420, 850)
    print("fold pixel (1420,850) scrollY0:", px_fold)
    thesisY = pg.evaluate("""() => {
      const el = document.querySelector('.panel-thesis');
      const r = el.getBoundingClientRect();
      return r.top + window.scrollY + r.height/2 - window.innerHeight/2;
    }""")
    pg.evaluate(f"window.scrollTo(0,{thesisY})")
    pg.wait_for_timeout(500)
    px_thesis = sample(1420, 850)
    print("thesis-centered pixel (1420,850):", px_thesis)
    giantY = pg.evaluate("""() => {
      const el = document.querySelector('.panel-giant');
      const r = el.getBoundingClientRect();
      return r.top + window.scrollY - 200;
    }""")
    pg.evaluate(f"window.scrollTo(0,{giantY})")
    pg.wait_for_timeout(500)
    px_giant = sample(1420, 850)
    print("giant.top-200 pixel (1420,850):", px_giant)
    b.close()

def chdelta(a,b):
    return max(abs(a[i]-b[i]) for i in range(3))
print("delta fold vs thesis:", chdelta(px_fold, px_thesis))
EOF
