file.content:
     tråden var färdigritad innan liggaren var läsbar (H-25).
     AVVIKELSE från planens 0,62/0,95 (steg 2 kräver ommätning och
     justering om talen skiljer mer än 0,05, vilket de gjorde här):
     egen bisektionssökning i R6-läget gav ps 0,364 vid liggarens
     överkant +600px (scrollY 2748) och ps 0,679 vid +90px
     (scrollY 3258) - start 0,364, bredd 0,315. */
  --scrub:clamp(0,calc((var(--sc-ps,0) - 0.364) / 0.315),1);}
.giant{font-family:var(--f-display);font-weight:700;
  /* PLAN 014, T-5: taket 4,8rem (76,8px) band under TASTE § 2.4:s
     5x-golv (80px). 6,7vw = 96,5px vid 1440, taket 6rem (96px) binder. */
  font-size:clamp(2.1rem,6.7vw,6rem);line-height:.96;letter-spacing:-.03em;
  text-transform:uppercase;text-wrap:balance;overflow-wrap:anywhere;min-width:0;
  /* AVVIKELSE: taket (96px) mätt i den faktiska högerspalten (555px
     textbredd, inte planens antagna 640px) tvingar "VARUMÄRKE." (601px
     som ett ord vid 96px) att kapas MITT I ORDET av overflow-wrap:anywhere
     ("VARUMÄRK/E."), 4 rader i stället för planens mål 3. hyphens:auto
     (lang="sv" finns på <html>) ger en riktig stavelsedelning i stället
     för ett godtyckligt teckensnitt; overflow-wrap:anywhere står kvar
     som sista skydd om ett ord ändå inte kan delas. */
  hyphens:auto;

