with sync_playwright() as p:
    b = p.chromium.launch()
    for w, h in [(390, 844), (375, 812), (414, 896)]:
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(BASE, wait_until="load")
        pg.wait_for_timeout(500)
        r = pg.evaluate("""() => {
          const sub = document.querySelector('.hero-sub').getBoundingClientRect();
          const headline = document.querySelector('.hero-headline').getBoundingClientRect();
          const topline = document.querySelector('.topline, .topline-contact')?.closest('header, .topline-row, nav') || document.querySelector('a.topline-contact');
          const toplineRect = topline ? topline.getBoundingClientRect() : null;
          return { subBottom: sub.bottom, headlineTop: headline.top, toplineBottom: toplineRect ? toplineRect.bottom : null };
        }""")
        deadGround = h - r["subBottom"]
