        gap = r["headlineTop"] - (r["toplineBottom"] or 0)
        print(f"{w}x{h}: deadGround={deadGround:.1f}px ({pct:.1f}%) headline-topline gap={gap:.1f}px")
        pg.close()
    # 320x568 check
    pg = b.new_page(viewport={"width": 320, "height": 568})
    pg.goto(BASE, wait_until="load")
    pg.wait_for_timeout(500)
    r = pg.evaluate("""() => {
      const sub = document.querySelector('.hero-sub').getBoundingClientRect();
      const headline = document.querySelector('.hero-headline').getBoundingClientRect();
      const toplineRect = document.querySelector('a.topline-contact').getBoundingClientRect();
      return { subBottom: sub.bottom, headlineTop: headline.top, toplineBottom: toplineRect.bottom };
    }""")
    print(f"320x568: subBottom={r['subBottom']:.1f} (<=568? {r['subBottom']<=568}) headline-topline gap={r['headlineTop']-r['toplineBottom']:.1f}")
    pg.close()
    b.close()
EOF
